/* A concept may resolve a job name the catalogue does not hold:
   `landing` renders `past` unscrolled. */

function scenarioName() {
  var m = /[?&]s=([a-z-]+)/.exec(location.search);
  return m ? m[1] : Object.keys(SCENARIOS)[0];
}
